import { ref, shallowRef } from 'vue';
import {
	createAsamFieldModes,
	createAsamWriteCoordinator,
	useAsamTableRange
} from '@asam-ui/pro/components';
import type {
	AsamRangeColumn,
	AsamFieldDefinition,
	AsamTransferWriteResult,
	AsamTransferOperation,
	AsamTransferContext
} from '@asam-ui/pro/components';
import type { AsamRowKey } from '@asam-ui/ui';
import { variant } from './Variant';
export interface Row {
	id: AsamRowKey;
	[field: string]: unknown;
}
export function createRangeHost(instance: string, coordinator = createAsamWriteCoordinator()) {
	const records: Row[] = Array.from({ length: 100 }, (_, i) => ({
		id: i === 1 ? '0' : i,
		name: `记录 ${i + 1}`,
		qty: i,
		enabled: i % 2 === 0,
		f1: '中文',
		f2: 'tab\t与"引号"',
		f3: '第一行\n第二行',
		f4: '0007',
		f5: i === 0 ? '=SUM(1,2)' : '字面.$&',
		f6: null,
		f7: undefined,
		secret: '敏感资料',
		locked: '只读'
	}));
	delete records[0].f7;
	const page = ref(0),
		revision = ref(0),
		identity = ref('合成用户'),
		scope = ref('range-demo');
	const disabled = ref(false),
		readonly = ref(false),
		readDelay = ref(variant.readDelayMs),
		writeDelay = ref(0),
		editingBusy = ref(false),
		refreshFail = ref(false),
		service = ref<'success' | 'partial' | 'unknown'>('success');
	const visible = shallowRef<readonly Row[]>(records.slice(0, 20));
	const pending = ref(0),
		reads = ref(0),
		calls = ref(0),
		verifies = ref(0),
		refreshes = ref(0);
	const remote = new Map<string, AsamTransferWriteResult>();
	const fields: readonly AsamFieldDefinition[] = [
		{ key: 'name', kind: 'text', label: variant.nameLabel },
		{ key: 'qty', kind: 'single', label: '数量' },
		{ key: 'enabled', kind: 'single', label: '启用' },
		...Array.from({ length: 7 }, (_, i) => ({
			key: `f${i + 1}`,
			kind: 'text' as const,
			label: `文本${i + 1}`
		})),
		{ key: 'secret', kind: 'text', label: '敏感' },
		{ key: 'locked', kind: 'text', label: '只读', modes: { edit: { readonly: true } } }
	];
	const modes = createAsamFieldModes({
		bindings: fields.map((field) => ({ field })),
		submit: fields
			.filter((f) => f.key !== 'secret' && f.key !== 'locked')
			.map((f) => ({ field: f.key, output: f.key }))
	});
	const columns = shallowRef<readonly AsamRangeColumn<Row>[]>(
		fields.map((field) => ({
			field: field.key,
			label: field.label,
			writable: field.key !== 'locked',
			sensitive: field.key === 'secret',
			read: async (row) => {
				const v = row[field.key];
				pending.value++;
				reads.value++;
				try {
					if (readDelay.value) await new Promise((r) => setTimeout(r, readDelay.value));
					return v === undefined ? '<undefined>' : v === null ? '<null>' : String(v);
				} finally {
					pending.value--;
				}
			}
		}))
	);
	function operation(
		op: AsamTransferOperation,
		status: 'saving' | 'unknown' | 'success' | 'not-applied'
	) {
		return {
			target: { mode: 'edit' as const, id: op.row.key, operationId: op.operationId },
			scope: op.scope,
			startedAt: Date.now(),
			input: op.row.model,
			payload: op.row.payload ?? {},
			status
		};
	}
	const external = {
		prepare: async (op: AsamTransferOperation, context: AsamTransferContext) => {
			return async (): Promise<AsamTransferWriteResult> => {
				pending.value++;
				try {
					if (writeDelay.value) await new Promise((r) => setTimeout(r, writeDelay.value));
					// 宿主最后异步适配后、真实合成服务前检查，不能只检查按钮。
					if (!context.canCommit() || disabled.value || readonly.value)
						return { status: 'not-applied', message: '最终服务前权限或投影变化' };
					const row = records.find((r) => r.id === op.row.key);
					if (!row) return { status: 'not-applied', message: 'typed key不存在' };
					const latest = coordinator.get(op.scope, op.operationId);
					if (
						latest &&
						(latest.target.id !== op.row.key ||
							Object.keys(latest.input).length !== Object.keys(op.row.model).length ||
							Object.keys(op.row.model).some(
								(key) =>
									!Object.hasOwn(latest.input, key) ||
									!Object.is(latest.input[key], op.row.model[key])
							))
					)
						return { status: 'not-applied', message: '操作ID已绑定其他意图' };
					if (latest?.status === 'success') return { status: 'success' };
					if (latest?.status === 'saving' || latest?.status === 'unknown')
						return { status: 'unknown', message: '同操作正在发送或需核实' };
					coordinator.set(operation(op, 'saving'));
					calls.value++;
					if (service.value === 'partial' && op.row.key === '0') {
						coordinator.set(operation(op, 'not-applied'));
						return { status: 'not-applied', message: '合成第二行明确拒绝' };
					}
					Object.assign(row, op.row.payload);
					remote.set(op.operationId, { status: 'success' });
					if (service.value === 'unknown') {
						coordinator.set(operation(op, 'unknown'));
						return { status: 'unknown', message: '合成响应丢失；不自动重发' };
					}
					coordinator.set(operation(op, 'success'));
					return { status: 'success' };
				} finally {
					pending.value--;
				}
			};
		},
		verify: async (
			op: AsamTransferOperation,
			context: AsamTransferContext
		): Promise<AsamTransferWriteResult> => {
			verifies.value++;
			if (!context.canCommit()) return { status: 'unknown', message: '身份或范围失效' };
			const result = remote.get(op.operationId) ?? {
				status: 'not-applied',
				message: '合成服务确认未应用'
			};
			coordinator.set(operation(op, result.status));
			return result;
		}
	};
	const controller = useAsamTableRange<Row>({
		projection: () => ({
			rows: visible.value,
			columns: columns.value,
			revision: revision.value
		}),
		keyOf: (row) => row.id,
		scope: () => scope.value,
		identity: () => identity.value,
		disabled: () => disabled.value,
		readonly: () => readonly.value,
		editingBusy: () => editingBusy.value,
		allowRaw: true,
		operationId: (draft, key) => `${instance}:${draft}:${typeof key}:${key}`,
		modes,
		external,
		convert: (field, cell) => {
			if (cell.text === '<undefined>') return undefined;
			if (cell.text === '<null>') return null;
			if (field === 'qty') {
				if (!/^-?\d+(?:\.\d+)?$/.test(cell.text)) throw Error('数量必须是有限数值');
				return Number(cell.text) * variant.quantityMultiplier;
			}
			if (field === 'enabled') {
				if (cell.text === 'true') return true;
				if (cell.text === 'false') return false;
				throw Error('启用必须是true/false');
			}
			return cell.text;
		},
		validate: async (row) =>
			Object.hasOwn(row.model, 'name') && row.model.name === ''
				? [{ field: 'name', message: '名称不能为空' }]
				: [],
		refresh: async () => {
			refreshes.value++;
			if (refreshFail.value) throw Error('合成刷新失败');
			visible.value = records
				.slice(page.value * 20, page.value * 20 + 20)
				.map((r) => ({ ...r }));
			revision.value++;
		}
	});
	return {
		controller,
		records,
		visible,
		columns,
		revision,
		identity,
		scope,
		disabled,
		readonly,
		readDelay,
		writeDelay,
		editingBusy,
		refreshFail,
		service,
		pending,
		reads,
		calls,
		verifies,
		refreshes,
		page,
		coordinator,
		nextPage() {
			page.value = (page.value + 1) % 5;
			visible.value = records.slice(page.value * 20, page.value * 20 + 20);
			revision.value++;
		},
		sort() {
			visible.value = [...visible.value].reverse();
			revision.value++;
		},
		hide() {
			columns.value = columns.value.filter((c) => c.field !== 'f7');
			revision.value++;
		}
	};
}

/** Agent可修改真实字段/转换/区域读取与查找配置；不只改标题。 */
export const variant = {
	nameLabel: '名称',
	quantityMultiplier: 1,
	readDelayMs: 100,
	defaultFind: '记录',
	defaultFindScope: 'current' as 'current' | 'selected'
};
